<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use MarketForecast\Database\Connection;
use MarketForecast\Reliability\{FrfCalculator,ReliabilityRepository};
$db=$argv[1]??dirname(__DIR__).'/database/forecast.sqlite';$pdo=Connection::open($db);$stats=$pdo->query("SELECT fp.experiment_id,COUNT(*) n,SUM(er.direction_correct) correct,AVG(er.brier_score) brier,AVG(er.absolute_error_pct) mae,MAX(fp.generated_at) last_at,MIN(fp.generated_at) first_at FROM final_predictions fp JOIN experiments e ON e.id=fp.experiment_id JOIN forecast_pairs p ON p.id=fp.forecast_pair_id JOIN final_predictions ai ON ai.forecast_pair_id=p.id AND ai.source_type='AI' JOIN evaluation_results er ON er.final_prediction_id=fp.id WHERE fp.source_type='QUANT' AND e.ai_activation_at IS NOT NULL AND fp.generated_at>=e.ai_activation_at AND ai.generated_at>=e.ai_activation_at GROUP BY fp.experiment_id")->fetchAll(PDO::FETCH_ASSOC);$calc=new FrfCalculator();$repo=new ReliabilityRepository($pdo);$done=0;
foreach($stats as $s){$n=(int)$s['n'];$end=(string)$s['last_at'];$scores=['direction'=>$calc->directionScore((int)$s['correct'],$n),'probability'=>$calc->probabilityScore((float)$s['brier'],$n),'return_error'=>$calc->returnErrorScore((float)$s['mae']),'consistency'=>100.0,'sample_size'=>$calc->sampleSizeScore($n),'time_coverage'=>100.0,'coverage'=>100.0,'regime_coverage'=>50.0,'data_quality'=>100.0];$fps=$calc->fps($scores);$ecs=$calc->ecs($scores);$frs=$calc->frs($fps,$ecs);$run=$repo->createRun(['experiment_id'=>$s['experiment_id'],'source_type'=>'QUANT','window_code'=>'ALL_TIME','window_start'=>$s['first_at'],'window_end'=>$end,'calculation_version'=>'FRF_V2_PROD','status'=>'FINALIZED','resolved_n'=>$n,'created_at'=>gmdate('c')]);if($run!==null){$repo->saveScore($run,['fps'=>$fps,'ecs'=>$ecs,'frs'=>$frs,'fps_label'=>$calc->label($fps,'fps'),'ecs_label'=>$calc->label($ecs,'ecs'),'frs_label'=>$calc->label($frs,'frs'),'diagnostics'=>['resolved_n'=>$n,'direction_correct'=>(int)$s['correct'],'mean_brier'=>(float)$s['brier'],'mean_absolute_error_pct'=>(float)$s['mae']],'created_at'=>gmdate('c')]);$done++;}}
echo json_encode(['frf_runs_created'=>$done],JSON_THROW_ON_ERROR).PHP_EOL;
